select jsonb_build_object(
 'checked_at',clock_timestamp(),
 'new_table',to_regclass('private.arcade_bnb_run_reviews')::text,
 'new_rpc',to_regprocedure('public.arcade_bnb_run_review_v1(text,jsonb)')::text,
 'columns',(select jsonb_agg(jsonb_build_object('table',table_name,'name',column_name,'type',data_type,'nullable',is_nullable,'default',column_default) order by table_name,ordinal_position) from information_schema.columns where table_schema='private' and table_name in ('arcade_bnb_test_sessions','arcade_bnb_test_challenges')),
 'tables',(select jsonb_agg(jsonb_build_object('name',c.relname,'rls',c.relrowsecurity,'acl',c.relacl::text,'constraints',(select jsonb_agg(pg_get_constraintdef(k.oid) order by k.conname) from pg_constraint k where k.conrelid=c.oid)) order by c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private' and c.relname in ('arcade_bnb_test_sessions','arcade_bnb_test_challenges')),
 'functions',(select jsonb_agg(jsonb_build_object('name',p.proname,'args',pg_get_function_identity_arguments(p.oid),'source_md5',md5(p.prosrc),'definition_md5',md5(pg_get_functiondef(p.oid)),'security_definer',p.prosecdef,'config',p.proconfig,'acl',p.proacl::text,'anon_execute',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated_execute',has_function_privilege('authenticated',p.oid,'EXECUTE'),'service_execute',has_function_privilege('service_role',p.oid,'EXECUTE')) order by p.proname) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'arcade_bnb_test_%'),
 'service_role',(select jsonb_build_object('bypass_rls',rolbypassrls,'superuser',rolsuper) from pg_roles where rolname='service_role'),
 'private_usage',jsonb_build_object('anon',has_schema_privilege('anon','private','USAGE'),'authenticated',has_schema_privilege('authenticated','private','USAGE'),'service',has_schema_privilege('service_role','private','USAGE')),
 'session_privileges',jsonb_build_object('anon_select',has_table_privilege('anon','private.arcade_bnb_test_sessions','SELECT'),'authenticated_select',has_table_privilege('authenticated','private.arcade_bnb_test_sessions','SELECT'),'service_select',has_table_privilege('service_role','private.arcade_bnb_test_sessions','SELECT'),'service_update',has_table_privilege('service_role','private.arcade_bnb_test_sessions','UPDATE'))
) as readiness;
